<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Кто и на каком основании проверяет казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Проверки проводит Федеральное казначейство как орган внутреннего государственного финансового контроля на основании статьи 269.2 Бюджетного кодекса и федеральных стандартов внутреннего госфинконтроля, утверждённых постановлениями Правительства РФ."}}, {"@type": "Question", "name": "Какие бывают проверки казначейства?", "acceptedAnswer": {"@type": "Answer", "text": "Контроль ведётся в формах камеральной и выездной проверки, ревизии и обследования. Камеральная — по документам без выезда, выездная — по месту нахождения объекта, ревизия — комплексная проверка, обследование — анализ отдельных вопросов."}}, {"@type": "Question", "name": "Что проверяет казначейство при сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Прежде всего целевое использование средств, раздельный учёт результатов финансово-хозяйственной деятельности, соответствие операций первичным документам и условиям контракта, корректность распоряжений и сведений, обоснованность авансирования."}}, {"@type": "Question", "name": "Как подготовиться к проверке казначейства?", "acceptedAnswer": {"@type": "Answer", "text": "Собрать и систематизировать документы по контракту, проверить раздельный учёт и его методику в учётной политике, провести предпроверочный аудит по блокам — целевое использование, подтверждённость операций, учёт — и устранить слабые места заранее."}}, {"@type": "Question", "name": "Какие права у проверяемого?", "acceptedAnswer": {"@type": "Answer", "text": "Знакомиться с решением и программой проверки, получать разъяснения по предмету, представлять документы и пояснения, присутствовать при контрольных действиях по выездной проверке, знакомиться с актом и подавать на него возражения."}}, {"@type": "Question", "name": "Что делать с актом проверки?", "acceptedAnswer": {"@type": "Answer", "text": "Внимательно изучить акт и в установленный срок подать письменные возражения по спорным выводам со ссылками на документы и нормы. Аргументированные возражения нередко снимают часть замечаний до итогового решения."}}, {"@type": "Question", "name": "Что такое представление и предписание казначейства?", "acceptedAnswer": {"@type": "Answer", "text": "Это меры по итогам проверки. Представление содержит информацию о нарушениях и требование рассмотреть их и устранить причины. Предписание — обязательное к исполнению требование устранить нарушения, а в установленных случаях возместить ущерб."}}, {"@type": "Question", "name": "Что будет, если не исполнить предписание?", "acceptedAnswer": {"@type": "Answer", "text": "Неисполнение обязательного предписания само по себе влечёт ответственность. При этом предписание можно обжаловать в установленном порядке, если для этого есть основания."}}, {"@type": "Question", "name": "На что чаще всего ссылаются проверяющие?", "acceptedAnswer": {"@type": "Answer", "text": "На классификатор нарушений, выявляемых в ходе государственного финансового контроля. Для участника сопровождения значимы нарушения по нецелевому использованию, несоблюдению условий предоставления средств и недостаткам учёта и оформления операций."}}, {"@type": "Question", "name": "Чем проверка отличается от санкционирования?", "acceptedAnswer": {"@type": "Answer", "text": "Санкционирование — это текущий контроль при проведении операций, когда казначейство не пропускает нецелевые платежи. Проверка — последующий контроль уже состоявшегося расходования, поэтому к ней готовятся заранее, выстраивая документооборот."}}]}
</script>
